From f425959a2788aa5723084fa7086041d87b7340ba Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:43:39 +0100
Subject: [PATCH] plasmoid: toggle presentation mode on middle click

Unlike other tray applets, middle-clicking the Display Configuration
icon did nothing. Move the presentation mode toggle out of the switch so
middle-click can use it too, and mention it in the tooltip like others.

BUG: 426427
---
 plasmoid/PresentationModeItem.qml | 28 +++++----------------------
 plasmoid/main.qml                 | 32 +++++++++++++++++++++++++++++--
 2 files changed, 35 insertions(+), 25 deletions(-)

diff --git a/plasmoid/PresentationModeItem.qml b/plasmoid/PresentationModeItem.qml
index 8d296797..f4036ad1 100644
--- a/plasmoid/PresentationModeItem.qml
+++ b/plasmoid/PresentationModeItem.qml
@@ -18,6 +18,9 @@ ColumnLayout {
     id: root

     property alias checked: presentationModeSwitch.checked
+    property bool switchEnabled: true
+
+    signal toggled

     spacing: Kirigami.Units.smallSpacing

@@ -28,29 +31,8 @@ ColumnLayout {
         Layout.bottomMargin: -root.spacing
         text: i18n("Enable Presentation Mode")

-        onToggled: {
-            // disable Switch while job is running
-            enabled = false;
-
-            const service = pmSource.serviceForSource("PowerDevil"); // qmllint disable unqualified
-
-            if (checked) {
-                const op = service.operationDescription("beginSuppressingScreenPowerManagement");
-                op.reason = i18n("User enabled presentation mode");
-
-                const job = service.startOperationCall(op);
-                job.finished.connect(job => {
-                    enabled = true;
-                });
-            } else {
-                const op = service.operationDescription("stopSuppressingScreenPowerManagement");
-
-                const job = service.startOperationCall(op);
-                job.finished.connect(job => {
-                    enabled = true;
-                });
-            }
-        }
+        enabled: root.switchEnabled
+        onToggled: root.toggled()
     }

     PlasmaExtras.DescriptiveLabel {
diff --git a/plasmoid/main.qml b/plasmoid/main.qml
index 326027db..949854c5 100644
--- a/plasmoid/main.qml
+++ b/plasmoid/main.qml
@@ -23,12 +23,38 @@ PlasmoidItem {
     // Only show if the user enabled presentation mode
     Plasmoid.status: presentationModeEnabled ? PlasmaCore.Types.ActiveStatus : PlasmaCore.Types.PassiveStatus
     Plasmoid.icon: "preferences-desktop-display-randr-symbolic"
-    toolTipSubText: presentationModeEnabled ? i18n("Presentation mode is enabled") : ""
+    toolTipSubText: presentationModeEnabled ? i18n("Presentation mode is enabled; middle-click to disable") : i18n("Middle-click to enable presentation mode")

     readonly property string kcmName: "kcm_kscreen"
     readonly property bool kcmAllowed: KConfig.KAuthorized.authorizeControlModule("kcm_kscreen")

     property bool presentationModeEnabled: false
+    property bool presentationModeChanging: false
+
+    Plasmoid.onSecondaryActivated: setPresentationModeEnabled(!presentationModeEnabled)
+
+    function setPresentationModeEnabled(enabled: bool): void {
+        if (presentationModeChanging || enabled === presentationModeEnabled) {
+            return;
+        }
+
+        const service = pmSource.serviceForSource("PowerDevil");
+        let op;
+        if (enabled) {
+            op = service.operationDescription("beginSuppressingScreenPowerManagement");
+            op.reason = i18n("User enabled presentation mode");
+        } else {
+            op = service.operationDescription("stopSuppressingScreenPowerManagement");
+        }
+
+        // disable the switch while the job is running
+        presentationModeChanging = true;
+        const job = service.startOperationCall(op);
+        job.finished.connect(job => {
+            presentationModeChanging = false;
+        });
+        presentationModeEnabled = enabled;
+    }

     P5Support.DataSource {
         id: pmSource
@@ -89,7 +115,9 @@ PlasmoidItem {
             Layout.topMargin: Kirigami.Units.smallSpacing * 2
             Layout.leftMargin: Kirigami.Units.smallSpacing
             Layout.rightMargin: Kirigami.Units.smallSpacing
-            onCheckedChanged: root.presentationModeEnabled = checked
+            checked: root.presentationModeEnabled
+            switchEnabled: !root.presentationModeChanging
+            onToggled: root.setPresentationModeEnabled(checked)
         }

         // compact the layout
-- 
